                          <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-white rounded-full px-3 py-1 shadow-xl flex gap-1">
                            {[...Array(5)].map((_, i) => (
                              <Star key={i} size={11} fill="#f8c8c4" stroke="#f8c8c4" />
                            ))}
                          </div>
