    setIsSyncing(true);
    setCloudStatus('loading');
    try {
      const payload = {
        slides, 
        sectionImages, 
        socialLinks, 
        emailConfig, 
        notices, 
        reviews, 
        partners, 
        googleMapsLink,
        contactPhone,
        addressDetail,
        adminUsername,
        adminPassword,
        version: "1.2",
        lastSync: new Date().toISOString()
      };

      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });

      setCloudStatus('connected');
      setTimeout(() => setIsSyncing(false), 2000);
      return true;
    } catch (err) {
