             <div className="flex flex-col gap-1 min-w-0"><span className="text-[8px] font-black uppercase tracking-[0.3em] text-white/20">Endpoint SIR (Database API)</span><span className="text-[10px] font-mono text-[#f8c8c4]/60 break-all select-all leading-relaxed">{gasUrl}</span></div>
