// --- Special Effects Engine ---
const SpecialEffectsLayer = ({ config }: { config?: SpecialEventConfig }) => {
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    if (config?.active && config?.expiryDate) {
      const now = new Date();
      const expiry = new Date(config.expiryDate);
      if (now > expiry) setIsExpired(true);
    }
  }, [config]);

  if (!config?.active || isExpired) return null;

  return (
    <div className="fixed inset-0 pointer-events-none z-[1500] overflow-hidden">
      <style>{config.css}</style>
      {config.effectType === 'particles' && (
        <div className="absolute inset-0">
          {[...Array(30)].map((_, i) => (
            <motion.div
              key={i}
              initial={{ 
                y: -20, 
                x: `${Math.random() * 100}%`, 
                opacity: 0,
                scale: Math.random() * 0.5 + 0.5 
              }}
              animate={{ 
                y: '110vh', 
                opacity: [0, 0.8, 0],
                x: `${(Math.random() * 100) + (Math.sin(i) * 5)}%` 
              }}
              transition={{ 
                duration: Math.random() * 5 + 5, 
                repeat: Infinity, 
                delay: Math.random() * 10,
                ease: "linear"
              }}
              className="absolute text-white/40 text-xl"
            >
              {config.particleChar || '•'}
            </motion.div>
          ))}
        </div>
      )}
      {config.effectType === 'overlay' && (
        <div className="absolute inset-0 bg-event-overlay opacity-30 mix-blend-overlay" />
      )}
    </div>
  );
};

