import { 
  Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, 
  Briefcase, CheckCircle, Image as ImageIcon, RotateCcw, Cloud, Mail, 
  Key, Server, Eye, EyeOff, ShieldCheck, Zap, AlertCircle, Loader2, 
  Info, Lightbulb, Check, Database, Download, Upload, FileJson, ExternalLink, Link, RefreshCw, CloudOff,
  Instagram, Linkedin, Palette, MessageSquare, Lock, Phone, MapPin, ToggleLeft, ToggleRight, Shield,
  Layout, Wand2, Sparkles, Calendar
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface Slide { id: string; title: string; description: string; image: string; tag: string; }
interface SpecialEventConfig { active: boolean; prompt: string; effectType: 'particles' | 'filter' | 'overlay'; css: string; particleChar: string; expiryDate: string; }
interface SiteConfig { logoUrl: string; companyName: string; companySubtitle: string; footerNote: string; footerCopyright: string; developedBy: string; specialEvent: SpecialEventConfig; }
interface SectionImages { about: string; careers: string; }
interface SocialLinks { instagram: string; linkedin: string; facebook: string; tiktok: string; youtube: string; }

interface AdminPanelProps {
  isOpen: boolean; onClose: () => void; onLogout: () => void;
  siteConfig: SiteConfig; setSiteConfig: (config: SiteConfig) => void;
  slides: Slide[]; setSlides: (slides: Slide[]) => void;
  sectionImages: SectionImages; setSectionImages: (imgs: SectionImages) => void;
  socialLinks: SocialLinks; setSocialLinks: (links: SocialLinks) => void;
  notices: any[]; setNotices: (n: any[]) => void;
  reviews: any[]; setReviews: (r: any[]) => void;
  partners: any[]; setPartners: (p: any[]) => void;
  googleMapsLink: string; setGoogleMapsLink: (l: string) => void;
  contactPhone: string; setContactPhone: (p: string) => void;
  addressDetail: string; setAddressDetail: (a: string) => void;
  adminUsername: string; setAdminUsername: (u: string) => void;
  adminPassword: string; setAdminPassword: (p: string) => void;
  activeTab: string; setActiveTab: (tab: any) => void;
  t: any; isSyncing: boolean; onResetDefaults: () => void;
  gasUrl: string; setGasUrl: (url: string) => void;
  onPublishToCloud: () => Promise<boolean | any>; cloudStatus: string;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, siteConfig, setSiteConfig, slides, setSlides, sectionImages, setSectionImages, socialLinks, setSocialLinks, activeTab, setActiveTab, t, isSyncing, onResetDefaults, gasUrl, onPublishToCloud, cloudStatus
}) => {
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [eventDuration, setEventDuration] = useState(7);
  const [isSaving, setIsSaving] = useState(false);

  if (!isOpen) return null;

  // Defensive access to specialEvent
  const specialEvent = siteConfig?.specialEvent || {
    active: false,
    prompt: "",
    effectType: 'particles',
    css: "",
    particleChar: "❄",
    expiryDate: ""
  };

  const handleMagicWand = async () => {
    if (!specialEvent.prompt) return;
    setIsAiGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: (process.env.API_KEY as string) });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a JSON object for a web effect. Prompt: ${specialEvent.prompt}. 
        Return strictly JSON with: 
        "css": "string containing safe CSS, use classes .event-particle or .event-overlay",
        "effectType": "particles" or "overlay",
        "particleChar": "one character/emoji",
        Example for snow: {"css": ".event-particle { color: white; }", "effectType": "particles", "particleChar": "❄"}`,
        config: { responseMimeType: "application/json" }
      });

      const config = JSON.parse(response.text || "{}");
      const expiry = new Date();
      expiry.setDate(expiry.getDate() + eventDuration);

      setSiteConfig({
        ...siteConfig,
        specialEvent: {
          ...specialEvent,
          ...config,
          active: true,
          expiryDate: expiry.toISOString()
        }
      });
    } catch (err) { console.error("AI Error:", err); }
    setIsAiGenerating(false);
  };

  const updateSiteConfig = (field: keyof SiteConfig, value: any) => setSiteConfig({ ...siteConfig, [field]: value });

  return (
    <motion.div initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }} className="fixed inset-0 z-[2000] bg-[#081221] text-white overflow-y-auto">
      <div className="container mx-auto px-8 md:px-32 py-24">
        <div className="flex justify-between items-center mb-16">
          <h2 className="heading-serif text-5xl">Painel de Controlo</h2>
          <button onClick={onClose}><X size={32}/></button>
        </div>

        <div className="grid grid-cols-4 lg:grid-cols-8 gap-4 mb-16">
          {['site', 'slides', 'images', 'email', 'user'].map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`p-6 border text-[10px] font-bold tracking-widest uppercase ${activeTab === tab ? 'border-[#f8c8c4] text-[#f8c8c4]' : 'border-white/5 text-white/20'}`}>
              {tab}
            </button>
          ))}
        </div>

        <div className="min-h-[60vh]">
          {activeTab === 'site' && (
            <div className="space-y-16">
              {/* Branding Section */}
              <div className="crystal-card p-12 space-y-8">
                <h3 className="text-xl tracking-widest uppercase flex items-center gap-4"><Layout size={20}/> Identidade Visual</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2"><label className="admin-label">Nome Empresa</label><input value={siteConfig.companyName} onChange={e => updateSiteConfig('companyName', e.target.value)} className="admin-input" /></div>
                  <div className="space-y-2"><label className="admin-label">Logomarca (URL)</label><input value={siteConfig.logoUrl} onChange={e => updateSiteConfig('logoUrl', e.target.value)} className="admin-input" /></div>
                </div>
              </div>

              {/* Special Events - Magic Wand Section */}
              <div className="crystal-card p-12 space-y-10 border-[#f8c8c4]/20 bg-[#f8c8c4]/5">
                <div className="flex justify-between items-center">
                  <h3 className="text-xl tracking-widest uppercase flex items-center gap-4 text-[#f8c8c4]"><Wand2 size={24}/> Vara Mágica (IA de Eventos)</h3>
                  <div className={`px-3 py-1 rounded-full text-[8px] font-bold tracking-widest uppercase ${specialEvent.active ? 'bg-green-500/20 text-green-400' : 'bg-white/5 text-white/20'}`}>
                    {specialEvent.active ? 'Efeito Ativo' : 'Inativo'}
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-4">
                    <label className="admin-label">O que você deseja para o site hoje?</label>
                    <div className="flex gap-4">
                      <input 
                        value={specialEvent.prompt} 
                        onChange={e => setSiteConfig({...siteConfig, specialEvent: {...specialEvent, prompt: e.target.value}})}
                        placeholder="Ex: Clima de Natal com neve caindo suavemente..." 
                        className="admin-input flex-1 !bg-white/10" 
                      />
                      <button 
                        onClick={handleMagicWand}
                        disabled={isAiGenerating}
                        className="btn-serenity !bg-[#f8c8c4] !text-[#081221] !px-8 flex items-center gap-3 active:scale-95 disabled:opacity-50"
                      >
                        {isAiGenerating ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}
                        {isAiGenerating ? 'CRIANDO...' : 'LANÇAR FEITIÇO'}
                      </button>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-white/5">
                    <div className="space-y-4">
                       <label className="admin-label flex items-center gap-2"><Calendar size={14}/> Duração do Feitiço (Dias)</label>
                       <div className="flex items-center gap-6">
                         <input type="range" min="1" max="30" value={eventDuration} onChange={e => setEventDuration(parseInt(e.target.value))} className="flex-1 accent-[#f8c8c4]" />
                         <span className="text-2xl font-light w-12 text-[#f8c8c4]">{eventDuration}d</span>
                       </div>
                    </div>
                    <div className="space-y-4 flex flex-col justify-end">
                      <button 
                        onClick={() => setSiteConfig({...siteConfig, specialEvent: {...specialEvent, active: false}})}
                        className="text-[9px] font-bold tracking-[0.4em] uppercase text-white/20 hover:text-red-400 transition-colors"
                      >
                        Remover Todos os Efeitos
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'slides' && (
            <div className="space-y-8">
              {slides && Array.isArray(slides) && slides.map(s => (
                <div key={s.id} className="crystal-card p-8 grid grid-cols-2 gap-8">
                   <input value={s.title} className="admin-input" />
                   <input value={s.image} className="admin-input" />
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="mt-24 pt-16 border-t border-white/5 flex flex-col items-center gap-8">
           <button 
            onClick={async () => { setIsSaving(true); await onPublishToCloud(); setIsSaving(false); onClose(); }} 
            className="btn-serenity px-32 py-8 flex items-center gap-4"
           >
             {isSaving ? <Loader2 className="animate-spin" /> : <Save size={18}/>}
             {isSaving ? 'SALVANDO...' : 'GUARDAR ALTERAÇÕES'}
           </button>
        </div>
      </div>

      <style>{`
        .admin-label { display: block; font-size: 10px; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase; color: rgba(255,255,255,0.4); margin-bottom: 0.5rem; }
        .admin-input { width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 1.2rem; color: white; border-radius: 2px; outline: none; }
        .admin-input:focus { border-color: #f8c8c4; }
      `}</style>
    </motion.div>
  );
};

export default AdminPanel;
